select * from customer limit 3;

--Q1. What is the total revenue generated by male vs. female customers?
select gender, sum(purchase_amount) as total_revenue from customer  group by gender;

/* Male customers are the primary revenue driver for this business, generating $157,890 
  compared to $75,191 from Female customers.*/

--Q2. Which customers used a discount but still spent more than the average purchase amount?
select customer_id, purchase_amount  from customer where discount_applied='Yes' and purchase_amount >(select avg(purchase_amount) from customer);

/* Out of 3,900 total transactions, 839 customers used a promotional discount but 
  still maintained a final purchase amount higher than the company's average order value.*/

-- Q3. Which are the top 5 products with the highest average review rating?
select 	item_purchased, round(avg(review_rating)::numeric, 2) as avg_review_rating from customer group by item_purchased order by avg_review_rating desc limit 5;

/*  Gloves, Sandals, Boots, Hat, and Skirt represent the top 5 products with the 
  highest average review ratings, ranging from 3.78 to 3.86. */

--Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 
select round(avg(purchase_amount)::numeric, 3) as avg_purchase_amount, shipping_type from customer where shipping_type in ('Express', 'Standard') group by shipping_type;

/*Express shipping yields a higher average purchase amount ($60.48) compared 
  to standard shipping ($58.46).*/

--Q5. Do subscribed customers spend more? Compare average spend and total revenue 
--between subscribers and non-subscribers.
select subscription_status, round(avg(purchase_amount)::numeric, 3) as avg_spend, sum(purchase_amount) as total_revenue, 
count(*) as total_customers from customer group by subscription_status
order by avg_spend desc ; 

/* Non-subscribed customers account for the majority of the customer base (2,847) 
  and generate $170,436 in total revenue, compared to 1,053 subscribed customers who generate $62,645. */

--Q6. Which 5 products have the highest percentage of purchases with discounts applied?
select item_purchased,
count(*) as total_purchases, 
count(*) filter (where discount_applied = 'Yes') as total_purchase_with_discount,
Round((count(*) filter (where discount_applied = 'Yes'))::numeric/count(*) *100.0, 2) as perc_of_purchases
from customer group by item_purchased order by perc_of_purchases desc limit 5;	 

/*Hat (50.00%) and Sneakers (49.66%) lead the inventory with the highest percentage 
  of promotional discount applications, followed closely by Coat, Sweater, and Pants.*/


--Q7. Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment

select
case 
when previous_purchases<=1 then 'New'
when previous_purchases>=2 and previous_purchases<10 then 'Returning'
else 'Loyal'
end  as customer_segment,
count(*) as customer_count from customer group by customer_segment;

/* The retail customer base breaks down into 3,192 Loyal customers, 625 Returning customers, 
  and 83 New customers.*/

--Q8. What are the top 3 most purchased products within each category? 

WITH item_counts AS (
    SELECT category,
           item_purchased,
           COUNT(customer_id) AS total_orders,
           ROW_NUMBER() OVER (PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)
SELECT item_rank,category, item_purchased, total_orders
FROM item_counts
WHERE item_rank <=3;

/*Using window functions, the top 3 highest-volume products were isolated for each retail category:
  * Accessories: Jewelry (171 orders), Sunglasses (161 orders), Belt (161 orders).
  * Clothing: Blouse (171 orders), Pants (171 orders), Shirt (169 orders).
  * Footwear: Sandals (160 orders), Shoes (150 orders), Sneakers (145 orders).
  * Outerwear: Jacket (163 orders), Coat (161 orders).
  This ranking identifies our primary product-market fit anchors, revealing consistent high volume 
  for core apparel (Blouses/Pants) and key fashion accessories (Jewelry).*/

--Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT subscription_status,
       COUNT(customer_id) AS repeat_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;

/*Among highly active repeat buyers (those with more than 5 previous purchases), 2,518 
  customers do not hold an active premium membership, while 958 customers are subscribed.
  This indicates a critical conversion gap. Approximately 72.4% of the company's most frequent 
  and loyal shoppers are navigating transactions outside the premium membership tier. */
  
--Q10. What is the revenue contribution of each age group? 
SELECT 
    age_group,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY age_group
ORDER BY total_revenue desc;

/*Total retail revenue is fairly evenly distributed across demographics, with "Young Adult" leading 
  at $62,143, followed by "Middle-aged" ($59,197), "Adult" ($55,978), and "Senior" ($55,763). */





